        # Every frame paints two nested outlines, alternating their colors.
        if height < 5 or width < 5:
            return
        first = 2 if level % 2 == 0 else 5
        for inset, color in ((1, first), (2, 7 - first)):
            rt, rb, cl, cr = t + inset, b - inset, l + inset, r - inset
            for c in range(cl, cr + 1):
                out[rt][c] = out[rb][c] = color
            for rr in range(rt, rb + 1):
                out[rr][cl] = out[rr][cr] = color
        # Next pair starts three cells inward, so the two intervening rows
        # are untouched (and remain zero), as in the demonstrations.
        next_t, next_b = t + 3, b - 3
        next_l, next_r = l + 3, r - 3
        if next_b - next_t + 1 >= 5 and next_r - next_l + 1 >= 5:
            draw_pair(next_t, next_b, next_l, next_r, level + 1)

